import { useTranslation } from 'react-i18next';

import { supportedLngs } from './i18n';

export default function App() {
  const { t, i18n } = useTranslation();
  const count = 3;
  return (
    <main>
      <nav>
        <a href="/">{t('nav.dashboard')}</a>
        <a href="/tasks">{t('nav.tasks')}</a>
        <label>
          {t('language.label')}
          <select
            value={i18n.resolvedLanguage}
            onChange={(event) => i18n.changeLanguage(event.target.value)}
          >
            {Object.entries(supportedLngs).map(([lng, endonym]) => (
              <option key={lng} value={lng}>
                {endonym}
              </option>
            ))}
          </select>
        </label>
      </nav>
      <h1>{t('dashboard.welcome', { name: 'Alex' })}</h1>
      <p>{t('dashboard.tasksDue', { count })}</p>
      <button>{t('dashboard.addTask')}</button>
      <label>
        <input type="checkbox" /> {t('dashboard.emailUpdates')}
      </label>
    </main>
  );
}

import i18n from 'i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import { initReactI18next } from 'react-i18next';

import en from './locales/en/translation.json';
import es from './locales/es/translation.json';

// Language codes mapped to their endonym — the name shown in the language
// picker, always written in that language itself, so it is never translated.
export const supportedLngs = {
  en: 'English',
  es: 'Español',
};

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: en },
      es: { translation: es },
    },
    fallbackLng: 'en',
    supportedLngs: Object.keys(supportedLngs),
    // Let regional codes fall back to their base language: en-GB -> en.
    nonExplicitSupportedLngs: true,
    interpolation: {
      // React escapes interpolated values already.
      escapeValue: false,
    },
  });

// Keep the document in sync so screen readers, spellcheck and CSS :lang()
// see the active language, and RTL locales lay out correctly.
function syncDocumentLanguage(lng) {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = lng;
  document.documentElement.dir = i18n.dir(lng);
}

i18n.on('languageChanged', syncDocumentLanguage);
syncDocumentLanguage(i18n.resolvedLanguage ?? 'en');

export default i18n;

